  @override
  Future<Payment?> build() async => null;

  Future<void> pay({required int amountMinor, required String currency,
      required String paymentMethodId}) async {
    state = const AsyncLoading();
    state = await AsyncValue.guard(() => ref.read(paymentRepositoryProvider).pay(
          amountMinor: amountMinor, currency: currency,
          paymentMethodId: paymentMethodId,
