## iOS (Swift): `ios/Runner/AppDelegate.swift`

```swift
import Flutter
import UIKit

@main
@objc class AppDelegate: FlutterAppDelegate {
  override func application(
    _ application: UIApplication,
    didFinishLaunchingWithOptions launchOptions: [UIApplication.LaunchOptionsKey: Any]?
  ) -> Bool {
    GeneratedPluginRegistrant.register(with: self)

    if let registrar = self.registrar(forPlugin: "NativeUrlLauncher") {
      let channel = FlutterMethodChannel(
        name: "app/native_url_launcher",
        binaryMessenger: registrar.messenger()
      )
      channel.setMethodCallHandler { call, result in
        guard
          let args = call.arguments as? [String: Any],
          let urlString = args["url"] as? String,
          let url = URL(string: urlString)
        else {
          result(FlutterError(code: "INVALID_URL", message: "url is required", details: nil))
          return
        }

        switch call.method {
        case "canLaunch":
          result(UIApplication.shared.canOpenURL(url))
        case "launch":
          let externalOnly = args["externalOnly"] as? Bool ?? true
          // universalLinksOnly: true = only open if an app claims the link.
          let options: [UIApplication.OpenExternalURLOptionsKey: Any] =
            externalOnly ? [:] : [.universalLinksOnly: false]
          UIApplication.shared.open(url, options: options) { success in
            result(success)
          }
        default:
          result(FlutterMethodNotImplemented)
