Before you replace `url_launcher`, it's worth naming the specific gap. The maintained plugin already handles Android intents and package visibility, iOS `open(_:)`, web, desktop, and in-app browser modes, and it's tested across Flutter releases. If the reason is one of these, a smaller change may be enough:

- **Need a specific behavior** (custom Intent flags, a target package, Universal-Links-only): wrap the plugin and add a tiny channel just for that one behavior.
- **Want to drop a dependency or control the contract**: custom code is reasonable. It's below.

Here is a self-contained, app-local implementation (not a reusable package) for Android and iOS. Other platforms fail explicitly.

## Dart adapter

`lib/platform/url_launcher_channel.dart`

```dart
import 'package:flutter/foundation.dart';
import 'package:flutter/services.dart';

enum UrlLaunchFailure { invalidUrl, disallowedScheme, noHandler, unavailable, platformError }

class UrlLaunchException implements Exception {
  const UrlLaunchException(this.failure, [this.detail]);
  final UrlLaunchFailure failure;
  final String? detail;
  @override
  String toString() => 'UrlLaunchException(${failure.name}${detail == null ? '' : ': $detail'})';
}

class UrlLauncherChannel {
  UrlLauncherChannel({
    MethodChannel channel = const MethodChannel('com.example.app/url_launcher'),
    TargetPlatform? platform,
  })  : _channel = channel,
        _platform = platform;

  static const allowedSchemes = {'https', 'http', 'mailto', 'tel'};

  final MethodChannel _channel;
  final TargetPlatform? _platform;

  bool get isSupported {
    if (kIsWeb) return false;
    final p = _platform ?? defaultTargetPlatform;
    return p == TargetPlatform.android || p == TargetPlatform.iOS;
  }

  /// Throws [UrlLaunchException] on every failure path; never returns silently.
  Future<void> launch(Uri uri) async {
    if (!isSupported) {
      throw const UrlLaunchException(UrlLaunchFailure.unavailable, 'Unsupported platform');
    }
    if (!uri.hasScheme || uri.toString().isEmpty) {
      throw UrlLaunchException(UrlLaunchFailure.invalidUrl, uri.toString());
    }
    if (!allowedSchemes.contains(uri.scheme.toLowerCase())) {
      throw UrlLaunchException(UrlLaunchFailure.disallowedScheme, uri.scheme);
    }

    final bool? opened;
    try {
      opened = await _channel.invokeMethod<bool>('launch', {'url': uri.toString()});
    } on MissingPluginException {
      throw const UrlLaunchException(UrlLaunchFailure.unavailable, 'Native handler not registered');
    } on PlatformException catch (e) {
      throw UrlLaunchException(switch (e.code) {
        'invalid-argument' => UrlLaunchFailure.invalidUrl,
        'disallowed-scheme' => UrlLaunchFailure.disallowedScheme,
        _ => UrlLaunchFailure.platformError,
      }, e.message);
    }
    if (opened != true) {
      throw UrlLaunchException(UrlLaunchFailure.noHandler, uri.toString());
    }
  }
}
```

## Android (Kotlin)

`android/app/src/main/kotlin/com/example/app/UrlLauncherChannel.kt`

```kotlin
package com.example.app

import android.app.Activity
import android.content.ActivityNotFoundException
import android.content.Context
import android.content.Intent
import android.net.Uri
import io.flutter.embedding.engine.plugins.FlutterPlugin
import io.flutter.embedding.engine.plugins.activity.ActivityAware
import io.flutter.embedding.engine.plugins.activity.ActivityPluginBinding
import io.flutter.plugin.common.MethodCall
import io.flutter.plugin.common.MethodChannel

class UrlLauncherChannel : FlutterPlugin, ActivityAware, MethodChannel.MethodCallHandler {
    private var channel: MethodChannel? = null
    private var appContext: Context? = null
    private var activity: Activity? = null

    override fun onAttachedToEngine(binding: FlutterPlugin.FlutterPluginBinding) {
        appContext = binding.applicationContext
        channel = MethodChannel(binding.binaryMessenger, CHANNEL).also { it.setMethodCallHandler(this) }
    }

    override fun onDetachedFromEngine(binding: FlutterPlugin.FlutterPluginBinding) {
        channel?.setMethodCallHandler(null)
        channel = null
        appContext = null
    }

    override fun onAttachedToActivity(binding: ActivityPluginBinding) { activity = binding.activity }
    override fun onDetachedFromActivityForConfigChanges() { activity = null }
    override fun onReattachedToActivityForConfigChanges(binding: ActivityPluginBinding) { activity = binding.activity }
    override fun onDetachedFromActivity() { activity = null }

    override fun onMethodCall(call: MethodCall, result: MethodChannel.Result) {
        when (call.method) {
            "launch" -> launch(call, result)
            else -> result.notImplemented()
        }
    }

    private fun launch(call: MethodCall, result: MethodChannel.Result) {
        val raw = call.argument<String>("url")
        if (raw.isNullOrBlank()) {
            result.error("invalid-argument", "Missing 'url'", null); return
        }
        val uri = Uri.parse(raw)
        val scheme = uri.scheme?.lowercase()
        if (scheme == null || scheme !in ALLOWED_SCHEMES) {
            result.error("disallowed-scheme", "Scheme not allowed: $scheme", null); return
        }

        val intent = Intent(Intent.ACTION_VIEW, uri).addCategory(Intent.CATEGORY_BROWSABLE)
        // Prefer the Activity; fall back to the app context (e.g. background engine) with NEW_TASK.
        val starter: Context = activity ?: appContext?.also { intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK) }
            ?: run { result.error("unavailable", "No context attached", null); return }

        try {
            starter.startActivity(intent)
            result.success(true)
        } catch (e: ActivityNotFoundException) {
            result.success(false) // Dart maps to noHandler
        } catch (e: SecurityException) {
            result.error("launch-failed", e.message, null)
        }
    }

    companion object {
        const val CHANNEL = "com.example.app/url_launcher"
        val ALLOWED_SCHEMES = setOf("https", "http", "mailto", "tel")
    }
}
```

Register it in `MainActivity.kt`:

```kotlin
class MainActivity : FlutterActivity() {
    override fun configureFlutterEngine(flutterEngine: FlutterEngine) {
        super.configureFlutterEngine(flutterEngine)
        flutterEngine.plugins.add(UrlLauncherChannel())
    }
}
```

This calls `startActivity` and catches `ActivityNotFoundException` instead of pre-checking with `resolveActivity`. That means you don't need `<queries>` entries for Android 11+ package visibility. If you later add a "can launch?" check, you will need them.

## iOS (Swift)

`ios/Runner/UrlLauncherChannel.swift`

```swift
import Flutter
import UIKit

final class UrlLauncherChannel: NSObject, FlutterPlugin {
  static let channelName = "com.example.app/url_launcher"
  private static let allowedSchemes: Set<String> = ["https", "http", "mailto", "tel"]

  static func register(with registrar: FlutterPluginRegistrar) {
    let channel = FlutterMethodChannel(name: channelName, binaryMessenger: registrar.messenger())
    registrar.addMethodCallDelegate(UrlLauncherChannel(), channel: channel)
  }

  func handle(_ call: FlutterMethodCall, result: @escaping FlutterResult) {
    guard call.method == "launch" else {
      result(FlutterMethodNotImplemented); return
    }
    guard let args = call.arguments as? [String: Any],
          let raw = args["url"] as? String,
          let url = URL(string: raw) else {
      result(FlutterError(code: "invalid-argument", message: "Missing or malformed 'url'", details: nil)); return
    }
    guard let scheme = url.scheme?.lowercased(), Self.allowedSchemes.contains(scheme) else {
      result(FlutterError(code: "disallowed-scheme", message: "Scheme not allowed: \(url.scheme ?? "nil")", details: nil)); return
    }
    // Channel handlers run on the main thread; open(_:) must too.
    UIApplication.shared.open(url, options: [:]) { opened in
      result(opened) // false → Dart maps to noHandler
    }
  }
}
```

