```dart
import 'package:flutter/material.dart';

class AppDestination {
  const AppDestination({
    required this.label,
    required this.icon,
    required this.selectedIcon,
  });
  final String label;
  final IconData icon;
  final IconData selectedIcon;
}

enum NavLayout { bar, rail, drawer }

const double kRailBreakpoint = 600;
const double kDrawerBreakpoint = 1200;

NavLayout navLayoutFor(double width) {
  if (width >= kDrawerBreakpoint) return NavLayout.drawer;
  if (width >= kRailBreakpoint) return NavLayout.rail;
  return NavLayout.bar;
}

class AdaptiveNavScaffold extends StatelessWidget {
  const AdaptiveNavScaffold({
    super.key,
    required this.destinations,
    required this.selectedIndex,
    required this.onDestinationSelected,
    required this.body,
  });

  final List<AppDestination> destinations;
  final int selectedIndex;
  final ValueChanged<int> onDestinationSelected;
  final Widget body;

  @override
  Widget build(BuildContext context) {
    // LayoutBuilder keeps this correct even when the shell isn't full-window
    // (split view, embedded in a desktop pane, multi-window).
    return LayoutBuilder(
      builder: (context, constraints) {
        switch (navLayoutFor(constraints.maxWidth)) {
          case NavLayout.bar:
            return Scaffold(
              body: body,
              bottomNavigationBar: NavigationBar(
                selectedIndex: selectedIndex,
                onDestinationSelected: onDestinationSelected,
                destinations: [
                  for (final d in destinations)
                    NavigationDestination(
                      icon: Icon(d.icon),
                      selectedIcon: Icon(d.selectedIcon),
                      label: d.label,
                    ),
                ],
              ),
            );

          case NavLayout.rail:
            return Scaffold(
              body: Row(
                children: [
                  SafeArea(
                    right: false,
                    child: NavigationRail(
                      selectedIndex: selectedIndex,
                      onDestinationSelected: onDestinationSelected,
                      labelType: NavigationRailLabelType.all,
                      destinations: [
                        for (final d in destinations)
                          NavigationRailDestination(
                            icon: Icon(d.icon),
                            selectedIcon: Icon(d.selectedIcon),
                            label: Text(d.label),
                          ),
                      ],
                    ),
                  ),
                  const VerticalDivider(width: 1, thickness: 1),
                  Expanded(child: body),
                ],
              ),
            );

          case NavLayout.drawer:
            return Scaffold(
              body: Row(
                children: [
                  SafeArea(
                    right: false,
                    child: NavigationDrawer(
                      selectedIndex: selectedIndex,
                      onDestinationSelected: onDestinationSelected,
                      children: [
                        const SizedBox(height: 16),
                        for (final d in destinations)
                          NavigationDrawerDestination(
                            icon: Icon(d.icon),
                            selectedIcon: Icon(d.selectedIcon),
                            label: Text(d.label),
                          ),
                      ],
                    ),
                  ),
                  const VerticalDivider(width: 1, thickness: 1),
                  Expanded(child: body),
                ],
              ),
            );
        }
      },
    );
  }
}
```

## Shell that owns the state

```dart
class HomeShell extends StatefulWidget {
  const HomeShell({super.key});
  @override
  State<HomeShell> createState() => _HomeShellState();
}

class _HomeShellState extends State<HomeShell> {
  // The body moves between Scaffold.body and a Row child when the layout
  // switches. Without a GlobalKey, each tab's state (scroll position, form
  // input) would be rebuilt from scratch on every breakpoint crossing.
  final _bodyKey = GlobalKey();
  int _index = 0;

  static const _destinations = [
    AppDestination(label: 'Home', icon: Icons.home_outlined, selectedIcon: Icons.home),
    AppDestination(label: 'Search', icon: Icons.search_outlined, selectedIcon: Icons.search),
    AppDestination(label: 'Profile', icon: Icons.person_outline, selectedIcon: Icons.person),
  ];

  @override
  Widget build(BuildContext context) {
    return AdaptiveNavScaffold(
      destinations: _destinations,
      selectedIndex: _index,
      onDestinationSelected: (i) => setState(() => _index = i),
      body: KeyedSubtree(
        key: _bodyKey,
        child: IndexedStack(
          index: _index,
          children: const [HomePage(), SearchPage(), ProfilePage()],
        ),
      ),
    );
  }
}
```

**If you use `go_router`'s `StatefulShellRoute`:** pass `navigationShell` as `body`, use `navigationShell.currentIndex` for `selectedIndex`, and call `navigationShell.goBranch(i, initialLocation: i == navigationShell.currentIndex)` in `onDestinationSelected`. Selection then lives in the router and is shared across layouts automatically.

